p='src/core/gen/generate.ts'
s=open(p,encoding='utf-8',newline='').read()
a="console.error(`[tr] a${attempt} promise lakeShare"
assert s.count(a)==1
leak = r"""{ const fl = drainage(hLand, W, H, { eight: false }).filled; hy.lakes.forEach((l, k) => { let hd = 0, lo = 99, lt = -1; for (const i of l.tiles) { if ((held as ArrayLike<number>)[i] >= 0.1) hd++; if (hLand[i] < lo) { lo = hLand[i]; lt = i; } } if (hd * 2 >= l.tiles.length) return; const inL = new Set(l.tiles); const lim = fl[lt]; const prev = new Int32Array(N).fill(-2); prev[lt] = -1; const qq = [lt]; let end = -1; for (let z = 0; z < qq.length && end < 0; z++) { const c = qq[z]; const x = c % W, y = (c - x) / W; if (x === 0 || y === 0 || x === W - 1 || y === H - 1) { end = c; break; } for (const n of [c - 1, c + 1, c - W, c + W]) { if (n < 0 || n >= N || prev[n] !== -2 || hLand[n] > lim) continue; if ((n % W === 0 && x === W - 1) || (x === 0 && n % W === W - 1)) continue; prev[n] = c; qq.push(n); } } const path: number[] = []; for (let c = end; c >= 0; c = prev[c]) path.push(c); path.reverse(); const ex = path.findIndex((c) => !inL.has(c)); const e = ex >= 0 ? path[ex] : -1; const near = (c: number) => { let best = 1e9, who = ""; const cx = c % W, cy = (c - cx) / W; for (const r of hy.rivers) for (const [px, py] of r.params.path) { const d = Math.hypot(px - cx, py - cy); if (d < best) { best = d; who = r.role; } } return who + "~" + best.toFixed(1); }; console.error(`[tr]   leak lake${k} ${l.tiles.length}@${l.outletBed} lim ${lim} low [${lt % W},${Math.floor(lt / W)}] exit ${e < 0 ? "none" : `[${e % W},${Math.floor(e / W)}] h${hLand[e]} w${hy.water[e]} ${near(e)}`} edge [${end % W},${Math.floor(end / W)}] w${hy.water[end]} ${near(end)} pathW ${[...new Set(path.slice(Math.max(0, ex)).map((c) => hy.water[c]))].join("")}`); }); } """
s=s.replace(a, leak + a)
open(p,'w',encoding='utf-8',newline='').write(s)
